Here's an implementation of a queue data structure using two stacks in Python:

```python
class Queue:
    def __init__(self):
        self.stack_in = []
        self.stack_out = []

    def enqueue(self, item):
        self.stack_in.append(item)

    def dequeue(self):
        if not self.is_empty():
            return self.stack_out.pop()

    def is_empty(self):
        return len(self.stack_in) == 0 and len(self.stack_out) == 0

    def peek(self):
        if not self.is_empty():
            return self.stack_out[-1]

    def size(self):
        return len(self.stack_in) + len(self.stack_out)

    def clear(self):
        self.stack_in = []
        self.stack_out = []

    def display(self):
        print("Stack In:", self.stack_in)
        print("Stack Out:", self.stack_out)


# Example usage:
q = Queue()
q.enqueue(1)
q.enqueue(2)
q.enqueue(3)
print(q.size())  # Output: 3
print(q.peek())   # Output: 3
print(q.dequeue())  # Output: 3
print(q.peek())   # Output: 2
print(q.size())  # Output: 2
print(q.is_empty())  # Output: False
q.clear()
print(q.is_empty())  # Output: True
